"""Writes src/LegacyTables.h from research/mc_tables.json (tables read out of MfgConsole.dll)."""
import json
import os

here = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
d = json.load(open(os.path.join(here, 'research', 'mc_tables.json')))
BS = chr(92)


def esc(s):
    return s.replace(BS, BS + BS).replace('"', BS + '"')


o = ['#pragma once',
     '// Generated by tools/gen_legacy_tables.py from MfgConsole.dll (sha 25194ce2): the strType',
     '// table at 0x100324D0 (141 names, indexed by base form type, capped at 0x8C) and the',
     '// expression names at 0x10032708.',
     'namespace MfgLE { namespace Legacy {',
     'static const char* const kTypeNames[141]={']
o += ['    "%s",' % esc(s) for s in d['types']]
o += ['};', 'static const char* const kExpressionNames[17]={']
o += ['    "%s",' % esc(s) for s in d['expr']]
o += ['};', '}}', '']
open(os.path.join(here, 'src', 'LegacyTables.h'), 'w', newline='\r\n').write('\n'.join(o))
